<?php
declare(strict_types=1);
namespace Tests\Unit\Catalog;
use App\Application\Catalog\DTO\Request\QueueSyllabusProcessingRequestDto;use App\Application\Catalog\Mapper\SyllabusProcessingJobResponseMapper;use App\Application\Catalog\Port\TransactionManagerInterface;use App\Application\Catalog\Service\QueueSyllabusProcessingService;use App\Domain\Catalog\Entity\Syllabus;use App\Domain\Catalog\Entity\SyllabusProcessingJob;use App\Domain\Catalog\Repository\SyllabusProcessingJobRepositoryInterface;use App\Domain\Catalog\Repository\SyllabusRepositoryInterface;use PHPUnit\Framework\TestCase;
final class QueueSyllabusProcessingServiceTest extends TestCase { public function testReusesCurrentJobForSameDocument():void{$syllabi=new class implements SyllabusRepositoryInterface{public function save(Syllabus $syllabus):void{}public function findById(string $id):?Syllabus{return new Syllabus('syllabus','position','Edital',null,null,'/tmp/edit.pdf',str_repeat('a',64),'edit.pdf','application/pdf',1);}public function existsById(string $id):bool{return true;}public function existsForPosition(string $id,string $positionId):bool{return true;}public function listForPosition(string $positionId):array{return[];}};$jobs=new class implements SyllabusProcessingJobRepositoryInterface{public int $saved=0;public function save(SyllabusProcessingJob $job):void{$this->saved++;}public function findLatestForSyllabus(string $syllabusId):?SyllabusProcessingJob{return new SyllabusProcessingJob('job','syllabus',str_repeat('a',64),'PENDING',0,null,new \DateTimeImmutable());}public function claimNext():?SyllabusProcessingJob{return null;}};$transactions=new class implements TransactionManagerInterface{public function transactional(callable $callback):mixed{return $callback();}};$result=(new QueueSyllabusProcessingService($syllabi,$jobs,new SyllabusProcessingJobResponseMapper(),$transactions))->queue(new QueueSyllabusProcessingRequestDto('syllabus'));self::assertSame('job',$result->id);self::assertSame(0,$jobs->saved);} }
